GSD=.claude/gsd-core/bin/gsd-tools.cjs
INIT=$(node "$GSD" query init.manager)
if [[ "$INIT" == @file:* ]]; then INIT=$(cat "${INIT#@file:}"); fi
echo "$INIT" | node -e '
let d="";process.stdin.on("data",c=>d+=c).on("end",()=>{
const j=JSON.parse(d.replace(/^[^{]*/,""));
console.log("completed:",j.completed_count,"/",j.phase_count);
console.log("recommended:");
for(const r of j.recommended_actions) console.log("  -",r.action,"phase",r.phase,"—",r.reason);
console.log("phase70:",JSON.stringify(j.phases.find(p=>p.number==="70")?.completion_status),"deps_satisfied:",j.phases.find(p=>p.number==="70")?.deps_satisfied);
})'

cd /Users/myankelev/Code/random/cipher-box
GSD=.claude/gsd-core/bin/gsd-tools.cjs
INIT=$(node "$GSD" query init.manager)
if [[ "$INIT" == @file:* ]]; then INIT=$(cat "${INIT#@file:}"); fi
echo "$INIT" | node -e '
let d="";process.stdin.on("data",c=>d+=c).on("end",()=>{
const j=JSON.parse(d.replace(/^[^{]*/,""));
for(const p of j.phases.filter(p=>["69","70","71"].includes(p.number)))
  console.log(p.number, "disk="+p.disk_status, "compl="+p.completion_status, "phase_complete="+p.phase_complete, "deps_sat="+p.deps_satisfied, "dep_phases="+JSON.stringify(p.dep_phases));
})'

_GSD_SHIM_NAME="gsd-tools.cjs"; _GSD_RUNTIME_ROOT="${RUNTIME_DIR:-$(git rev-parse --show-toplevel 2>/dev/null || pwd)}"; GSD_TOOLS="/Users/myankelev/Code/random/cipher-box/.claude/gsd-core/bin/${_GSD_SHIM_NAME}"; gsd_run() { node "$GSD_TOOLS" "$@"; }
DISCUSS_MODE=$(gsd_run query config-get workflow.discuss_mode 2>/dev/null || echo "discuss")
echo "DISCUSS_MODE=$DISCUSS_MODE"

GSD_TOOLS="/Users/myankelev/Code/random/cipher-box/.claude/gsd-core/bin/gsd-tools.cjs"; gsd_run() { node "$GSD_TOOLS" "$@"; }
INIT=$(gsd_run query init.phase-op 71); [[ "$INIT" == @file:* ]] && INIT=$(cat "${INIT#@file:}")
echo "$INIT"

